package com.bank.security;

import java.util.logging.*;

public class HappyNumberDemo {
    private static final Logger log = Logger.getLogger(HappyNumberDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PinRuleValidator validator = new PinRuleValidator();

        int happy = 19;   // 1,82,68,100,1 → happy
        int unhappy = 20; // enters 4-loop → unhappy
        log.info(() -> "Code " + happy + " accepted? " + validator.isHappy(happy));
        log.info(() -> "Code " + unhappy + " accepted? " + validator.isHappy(unhappy));
    }
}

