class PinRuleValidator {
    private static final Logger log = Logger.getLogger(PinRuleValidator.class.getName());

    // Floyd on the digit-square-sum sequence. O(1) space.
    boolean isHappy(int n) {
        int slow = n, fast = next(n);
        while (fast != 1 && slow != fast) {
            slow = next(slow);          // +1 transformation
            fast = next(next(fast));    // +2 transformations
        }
        boolean happy = (fast == 1);
        if (!happy) log.warning(() -> "Code " + n + " loops (unhappy)");
        return happy;
    }

    // Sum of squares of decimal digits.
    private int next(int x) {
        int sum = 0;
        while (x > 0) {
            int d = x % 10;
            sum += d * d;
            x /= 10;
        }
        return sum;
    }
}

